// C++17. Run: ant2_extremum cases.txt [threads] [families|parents|direct|all]
// Case manifest generated by ant2_cases.py. A failed check aborts the scan.
#include <algorithm>
#include <array>
#include <atomic>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <map>
#include <mutex>
#include <set>
#include <sstream>
#include <stdexcept>
#include <string>
#include <thread>
#include <vector>

using namespace std;
constexpr int side = 2048, half = side / 2, period = 104;
constexpr int delta[] = {side, 1, -side, -1};
using Pair = array<int, 4>;
void require(bool b) {
    if (!b)
        throw runtime_error("failed geometric, replay or input check");
}
int cell(int x, int y) {
    require(abs(x) < half && abs(y) < half);
    return (y + half) * side + x + half;
}
int xof(int p) { return p % side - half; }
int yof(int p) { return p / side - half; }
struct Bounds {
    int x0 = 0, x1 = 0, y0 = 0, y1 = 0;
    void add(int x, int y, int radius = 0) {
        x0 = min(x0, x - radius);
        x1 = max(x1, x + radius);
        y0 = min(y0, y - radius);
        y1 = max(y1, y + radius);
    }
    bool contains(int x, int y) const { return x >= x0 && x <= x1 && y >= y0 && y <= y1; }
};
struct State {
    int pos = cell(0, 0), heading = 0, time = 0, mask = 0, count = 0;
};
struct Ray {
    int x, y;
    uint64_t colours;
};
struct Shape {
    vector<Ray> rays;
    int dx = 0, dy = 0;
};
array<array<Shape, 4>, period> shapes;
string doubled;
array<int, 1024> bad;
struct Board {
    vector<uint8_t> ink = vector<uint8_t>(side * side);
    Bounds box;
    void seed(int x, int y) {
        box.add(x, y);
        ink[cell(x, y)] = 1;
    }
    void clear() {
        for (int y = box.y0; y <= box.y1; y++)
            memset(&ink[cell(box.x0, y)], 0, box.x1 - box.x0 + 1);
        box = Bounds();
    }
    void copy_from(const Board &source) {
        box = source.box;
        for (int y = box.y0; y <= box.y1; y++) {
            int p = cell(box.x0, y);
            memcpy(&ink[p], &source.ink[p], box.x1 - box.x0 + 1);
        }
    }
};

void init_words() {
    Board blank;
    State a;
    string word;
    for (int i = 0; i < 9977 + period; i++) {
        int b = blank.ink[a.pos];
        blank.ink[a.pos] ^= 1;
        if (i >= 9977)
            word += char(b);
        a.heading = (a.heading + 1 - 2 * b) & 3;
        a.pos += delta[a.heading];
        require(abs(xof(a.pos)) < half - 2 && abs(yof(a.pos)) < half - 2);
    }
    doubled = word + word;
    bad.fill(1);
    for (int phase = 0; phase < period; phase++) {
        int m = 0;
        for (int j = 0; j < 10; j++)
            m = 2 * m + doubled[phase + j];
        bad[m] = 0;
        for (int h = 0; h < 4; h++) {
            vector<int> reads;
            int p = cell(0, 0), hd = h;
            for (int j = 0; j < period; j++) {
                reads.push_back(p);
                hd = (hd + 1 - 2 * doubled[phase + j]) & 3;
                p += delta[hd];
            }
            auto &shape = shapes[phase][h];
            int vx = xof(p), vy = yof(p);
            require(hd == h && abs(vx) == 2 && abs(vy) == 2);
            shape.dx = vx;
            shape.dy = vy;
            map<pair<int, int>, vector<int>> groups;
            for (int r : reads)
                groups[{xof(r) * vy - yof(r) * vx, (xof(r) % 2 + 2) % 2}].push_back(r);
            for (auto &entry : groups) {
                const auto &points = entry.second;
                int first = *min_element(points.begin(), points.end(),
                                         [&](int u, int v) { return xof(u) * vx < xof(v) * vx; });
                uint64_t bits = 0;
                for (int r : points) {
                    int k = (xof(r) - xof(first)) / vx;
                    require(k >= 0 && k < 62 && yof(r) == yof(first) + k * vy);
                    bits ^= (uint64_t(1) << (k + 1)) - 1;
                }
                shape.rays.push_back({xof(first), yof(first), bits});
            }
        }
    }
    require(count(bad.begin(), bad.end(), 0) == 84);
}

// On an observed block's forward half-rays the two translated boards must
// agree. At r+k*v the after-colour is the XOR of all block visit parities
// at r+j*v, j>=k (telescope from infinity, where the board is white).
bool permanent(const Board &b, int start, int heading, const string &word) {
    auto phase = doubled.find(word);
    if (word.size() != period || phase >= period)
        return false;
    const auto &s = shapes[phase][heading];
    for (const auto &ray : s.rays) {
        int x = xof(start) + ray.x, y = yof(start) + ray.y;
        auto expected = ray.colours;
        while (b.box.contains(x, y)) {
            if (b.ink[cell(x, y)] != (expected & 1))
                return false;
            expected >>= 1;
            x += s.dx;
            y += s.dy;
        }
        if (expected)
            return false;
    }
    return true;
}

template <bool Save> void advance(Board &b, State &a, int length, string *trace = nullptr) {
    require(length <= period);
    int x = xof(a.pos), y = yof(a.pos);
    require(abs(x) + length < half && abs(y) + length < half);
    b.box.add(x, y, length);
    int p = a.pos, h = a.heading, m = a.mask, c = a.count;
    for (int j = 0; j < length; j++) {
        int bit = b.ink[p];
        b.ink[p] ^= 1;
        h = (h + 1 - 2 * bit) & 3;
        p += delta[h];
        m = (2 * m + bit) & 1023;
        c += bad[m];
        if (Save)
            trace->push_back(char(bit));
    }
    // The caller discards the aggregate on any initial segment ending at time 9.
    a.pos = p;
    a.heading = h;
    a.mask = m;
    a.count = c;
    a.time += length;
}
void initial_nine(Board &b, State &a) {
    if (a.time >= 9)
        return;
    int saved = a.count;
    advance<false>(b, a, 9 - a.time);
    a.count = saved;
}
int finish(Board &b, State a) {
    initial_nine(b, a);
    string trace;
    trace.reserve(period);
    while (a.time < 1000000) {
        int old = a.count;
        for (int j = 0; j < 7; j++)
            advance<false>(b, a, period);
        if (a.count != old) {
            advance<false>(b, a, period);
            continue;
        }
        int p = a.pos, h = a.heading;
        trace.clear();
        advance<true>(b, a, period, &trace);
        if (permanent(b, p, h, trace))
            return a.count;
    }
    throw runtime_error("no permanent tail certificate before guard limit");
}

struct Job {
    char kind;
    Pair b;
    int s;
    vector<int> ms;
};
struct Results {
    long long families = 0, windows = 0, direct = 0, parents = 0, children = 0;
    int best = -1;
    set<Pair> winners;
    void add(int n, Pair cells) {
        if (cells[0] > cells[2] || (cells[0] == cells[2] && cells[1] > cells[3])) {
            swap(cells[0], cells[2]);
            swap(cells[1], cells[3]);
        }
        if (n > best) {
            best = n;
            winners.clear();
        }
        if (n == best)
            winners.insert(cells);
    }
};
void fixed(const Job &j, Board &board, Results &result) {
    auto [x, y, u, v] = j.b;
    board.seed(x, y);
    board.seed(u, v);
    State a;
    if (j.s < 0) {
        result.direct++;
        result.add(finish(board, a), j.b);
    } else {
        result.families++;
        string trace;
        trace.reserve(j.s + period);
        string prefix;
        advance<true>(board, a, 9, &prefix);
        a.count = 0;
        trace += prefix;
        while (a.time < j.s)
            advance<true>(board, a, min(period, j.s - a.time), &trace);
        int p = a.pos, h = a.heading;
        advance<true>(board, a, period, &trace);
        require(permanent(board, p, h, trace.substr(j.s, period)));
        for (int t : j.ms) {
            require(t >= 0 && t + period <= a.time);
            string block = trace.substr(t, period);
            if (doubled.find(block) >= period) {
                cerr << "noncanonical inserted block at " << x << " " << y << " " << u << " " << v
                     << " t=" << t << endl;
                throw runtime_error("inspect this family for unbounded anomaly counts");
            }
            result.windows++;
        }
        result.add(a.count, j.b);
    }
    board.clear();
}
void parent(const Job &j, Board &source, Board &child, vector<int> &visited, int tag, Results &r) {
    auto [x, y, tau, end] = j.b;
    source.seed(x, y);
    State a;
    const int first = cell(x, y);
    bool met = false;
    for (int t = 0; t < end; t++) {
        int p = a.pos, px = xof(p), py = yof(p);
        require(abs(px) < half - 1 && abs(py) < half - 1);
        source.box.add(px, py);
        if (visited[p] != tag) {
            visited[p] = tag;
            if (p == first) {
                require(t == tau);
                met = true;
            }
            if (t > tau) {
                require(met && source.ink[p] == 0);
                child.copy_from(source);
                child.seed(px, py);
                r.add(finish(child, a), {x, y, px, py});
                r.children++;
                child.clear();
            }
        }
        int bit = source.ink[p];
        source.ink[p] ^= 1;
        a.heading = (a.heading + 1 - 2 * bit) & 3;
        a.pos += delta[a.heading];
        a.mask = (2 * a.mask + bit) & 1023;
        if (t >= 9)
            a.count += bad[a.mask];
        a.time++;
    }
    require(met);
    source.clear();
    r.parents++;
}

int main(int argc, char **argv) {
    if (argc < 2 || argc > 4) {
        cerr << "ant2_extremum manifest [threads] [all|families|parents|direct]\n";
        return 2;
    }
    init_words();
    int threads = argc >= 3 ? stoi(argv[2]) : 1;
    string mode = argc >= 4 ? argv[3] : "all";
    require(threads > 0 &&
            (mode == "all" || mode == "families" || mode == "parents" || mode == "direct"));
    vector<Job> jobs;
    ifstream input(argv[1]);
    require(input.good());
    string line;
    while (getline(input, line)) {
        istringstream s(line);
        Job j{};
        s >> j.kind;
        for (int &v : j.b)
            require(bool(s >> v));
        if (j.kind == 'A') {
            require(bool(s >> j.s));
            int t;
            while (s >> t)
                j.ms.push_back(t);
        } else
            require(j.kind == 'P');
        if (mode == "all" || (mode == "parents" && j.kind == 'P') ||
            (mode == "families" && j.kind == 'A' && j.s >= 0) ||
            (mode == "direct" && j.kind == 'A' && j.s < 0))
            jobs.push_back(j);
    }
    require(!jobs.empty());
    atomic<size_t> next{0};
    atomic<int> complete{0};
    mutex logs;
    vector<thread> pool;
    vector<Results> stats(threads);
    for (int i = 0; i < threads; i++)
        pool.emplace_back([&, i] {
            Board source, child;
            vector<int> visited(side * side, -1);
            auto &r = stats[i];
            while (true) {
                size_t k = next++;
                if (k >= jobs.size())
                    break;
                if (jobs[k].kind == 'P')
                    parent(jobs[k], source, child, visited, int(k), r);
                else
                    fixed(jobs[k], child, r);
                int done = ++complete;
                if ((mode == "parents" && done % 200 == 0) ||
                    (mode != "parents" && done % 25000 == 0)) {
                    lock_guard<mutex> lock(logs);
                    cerr << "checked " << done << "/" << jobs.size() << " worker best " << r.best
                         << endl;
                }
            }
        });
    for (auto &t : pool)
        t.join();
    Results total;
    for (const auto &r : stats) {
        total.families += r.families;
        total.windows += r.windows;
        total.direct += r.direct;
        total.parents += r.parents;
        total.children += r.children;
        for (auto key : r.winners)
            total.add(r.best, key);
    }
    cout << "family anchors " << total.families << ", inserted words " << total.windows
         << ", direct slab cases " << total.direct << ", parents " << total.parents
         << ", concrete children " << total.children << ", maximum " << total.best << "\n";
    for (auto p : total.winners)
        cout << p[0] << " " << p[1] << " " << p[2] << " " << p[3] << "\n";
    return 0;
}
